<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import AdminNav from '../components/admin/AdminNav.vue'
import {adminApi,issueMessages,type AdminEventDetail,type AdminVenueSummary,type PublishPreview,type AdminSession} from '../api/adminApi'
import {fromBeijingInput,toBeijingInput} from '../utils/adminDateTime'
import {parseYuanPrice,formatFenPrice} from '../utils/adminMoney'
const route=useRoute(),router=useRouter(),id=ref(route.params.eventId as string|undefined)
const event=ref<AdminEventDetail>(),venues=ref<AdminVenueSummary[]>([]),preview=ref<PublishPreview>(),error=ref(''),notice=ref(''),busy=ref(false)
const form=ref({name:'',description:'',category:'演唱会',coverUrl:'/images/concert-cover.png',venueId:'',salesStartsAt:'',salesEndsAt:''})
const sessionForm=ref({hallName:'主场馆',startTime:'',gateTime:''}),editing=ref<string>(),prices=ref<Record<string,Record<string,string>>>({})
const draft=computed(()=>!event.value||event.value.status==='DRAFT')
function accept(e:AdminEventDetail){event.value=e;id.value=e.id;form.value={name:e.name,description:e.description,category:e.category,coverUrl:e.coverUrl,venueId:e.venueId,salesStartsAt:toBeijingInput(e.salesStartsAt),salesEndsAt:toBeijingInput(e.salesEndsAt)};preview.value=e.readiness;prices.value={};for(const s of e.sessions){prices.value[s.id]={};for(const p of s.prices)prices.value[s.id]![p.zoneId]=formatFenPrice(p.price)}}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>action(async()=>{venues.value=await adminApi.venues();if(id.value)accept(await adminApi.event(id.value))}))
function save(){return action(async()=>{const f=form.value;if(!draft.value&&id.value){accept(await adminApi.display(id.value,{name:f.name,description:f.description,category:f.category,coverUrl:f.coverUrl}))}else accept(await adminApi.saveEvent(id.value,{...f,salesStartsAt:fromBeijingInput(f.salesStartsAt),salesEndsAt:fromBeijingInput(f.salesEndsAt)}));await router.replace('/admin/events/'+id.value);notice.value='活动已保存'})}
function edit(s:AdminSession){editing.value=s.id;sessionForm.value={hallName:s.hallName,startTime:toBeijingInput(s.startTime),gateTime:toBeijingInput(s.gateTime)}}
function saveSession(){return action(async()=>{const s=sessionForm.value;accept(await adminApi.session(id.value!,editing.value,{hallName:s.hallName,startTime:fromBeijingInput(s.startTime),gateTime:fromBeijingInput(s.gateTime)}));editing.value=undefined;notice.value='场次已保存'})}
function savePrices(sid:string) {
  return action(async()=>{
    const values = event.value!.venue.zones.map(zone => ({
      zoneId: zone.id,
      price: parseYuanPrice(prices.value[sid]?.[zone.id] ?? ''),
    }))
    accept(await adminApi.prices(id.value!,sid,values))
    notice.value='区域票价已保存'
  })
}
function publish(){return action(async()=>{try{const result=await adminApi.publish(id.value!);accept(result.event);notice.value=result.disposition==='PUBLISHED_NOW'?'发布成功，消费者现在可以查看活动':'活动已经发布'}catch(e){preview.value=await adminApi.preview(id.value!);throw e}})}
watch(()=>route.params.eventId,async next=>{if(next===id.value)return;id.value=next as string|undefined;event.value=undefined;preview.value=undefined;editing.value=undefined;prices.value={};form.value={name:'',description:'',category:'演唱会',coverUrl:'/images/concert-cover.png',venueId:'',salesStartsAt:'',salesEndsAt:''};await action(async()=>{if(id.value)accept(await adminApi.event(id.value))})})
</script>
<template><main class="admin-page"><AdminNav/><h2>{{id?'编辑活动':'新建活动草稿'}}</h2><p v-if="error" role="alert" class="admin-alert">{{error}}</p><p v-if="notice" role="status" class="admin-success">{{notice}}</p><p v-if="!draft" class="admin-success">活动已发布。仅可修改展示信息，场馆、售票时间、场次和票价已冻结。</p><form class="admin-panel" @submit.prevent="save"><h2>1 · 基本信息与场馆</h2><fieldset :disabled="busy"><div class="admin-grid"><label>活动名称<input v-model="form.name" required/></label><label>分类<input v-model="form.category" required/></label><label>封面地址<input v-model="form.coverUrl" required maxlength="2000"/></label><label>场馆<select aria-label="场馆" v-model="form.venueId" required :disabled="!draft||Boolean(event?.sessions.length)"><option value="">请选择场馆</option><option v-for="v in venues" :key="v.id" :value="v.id">{{v.name}} · {{v.totalSeats}} 席</option></select></label><label>开售时间（北京时间）<input v-model="form.salesStartsAt" type="datetime-local" required :disabled="!draft"/></label><label>停售时间（北京时间）<input v-model="form.salesEndsAt" type="datetime-local" required :disabled="!draft"/></label></div><label>活动介绍<textarea v-model="form.description" maxlength="10000"/></label><p class="admin-muted">时间统一按北京时间（Asia/Shanghai）解释。</p><button class="primary">{{draft?'保存活动草稿':'保存展示信息'}}</button></fieldset></form><template v-if="event"><section class="admin-panel"><h2>2 · 场次与区域票价</h2><p v-if="!event.sessions.length" class="admin-muted">至少添加一个场次后才能发布。</p><article v-for="s in event.sessions" :key="s.id" class="admin-zone" :data-testid="'session-'+s.id"><h3>{{s.hallName}} · {{toBeijingInput(s.startTime).replace('T',' ')}}</h3><fieldset :disabled="busy||!draft"><div class="admin-grid"><label v-for="z in event.venue.zones" :key="z.id">{{z.name}} 票价（元）<input v-model="prices[s.id]![z.id]" type="text" inputmode="decimal" maxlength="64"/></label></div><div class="admin-actions" style="margin-top:14px"><button @click="savePrices(s.id)">保存区域票价</button><button @click="edit(s)">编辑场次</button><button @click="action(async()=>{accept(await adminApi.deleteSession(id!,s.id));editing=undefined})">删除场次</button></div></fieldset></article><form v-if="draft" @submit.prevent="saveSession"><fieldset :disabled="busy"><h3>{{editing?'修改场次':'添加场次'}}</h3><div class="admin-grid"><label>场馆厅名<input v-model="sessionForm.hallName" required/></label><label>开始时间（北京时间）<input v-model="sessionForm.startTime" type="datetime-local" required/></label><label>入场时间（北京时间）<input v-model="sessionForm.gateTime" type="datetime-local" required/></label></div><button style="margin-top:16px" class="primary">{{editing?'保存场次修改':'添加场次'}}</button><button v-if="editing" type="button" @click="editing=undefined">取消编辑</button></fieldset></form></section><section class="admin-panel"><h2>3 · 发布预览</h2><button :disabled="busy" @click="action(async()=>{accept(await adminApi.event(id!));preview=await adminApi.preview(id!)})">刷新发布预览</button><template v-if="preview"><p class="admin-summary">{{preview.sessionCount}} 场 · {{preview.expectedSessionSeatCount.toLocaleString()}} 张票</p><table class="admin-table"><thead><tr><th>区域</th><th>每场座位</th></tr></thead><tbody><tr v-for="z in preview.venue.zones" :key="z.id"><td>{{z.name}}</td><td>{{z.seatCount}}</td></tr></tbody></table><ul v-if="preview.issues.length" class="admin-alert"><li v-for="(issue,i) in preview.issues" :key="i">{{issueMessages[issue.code]??issue.message}}<span v-if="issue.zoneId"> · {{preview.venue.zones.find(z=>z.id===issue.zoneId)?.name}}</span><span v-if="issue.sessionId"> · {{event.sessions.find(s=>s.id===issue.sessionId)?.hallName}}</span></li></ul><p class="admin-muted">发布后座位方案、场次、售票时间和票价将冻结。</p><button v-if="draft" class="primary" :disabled="busy||!preview.publishable" @click="publish">确认发布</button><RouterLink v-else :to="'/events/'+id+'/sessions'">查看消费者活动页 →</RouterLink></template></section></template></main></template>
